import{_ as e,H as a,f as o,i as n}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"开篇词｜天作之合：LLM助力业务流程自动化","description":"","frontmatter":{},"headers":[{"level":2,"title":"什么是业务流程自动化？","slug":"什么是业务流程自动化","link":"#什么是业务流程自动化","children":[]},{"level":2,"title":"LLM 助力业务流程自动化","slug":"llm-助力业务流程自动化","link":"#llm-助力业务流程自动化","children":[]},{"level":2,"title":"LLM 应用开发框架的分类","slug":"llm-应用开发框架的分类","link":"#llm-应用开发框架的分类","children":[]},{"level":2,"title":"课程设计","slug":"课程设计","link":"#课程设计","children":[]},{"level":2,"title":"结语","slug":"结语","link":"#结语","children":[]}],"relativePath":"LLM自主智能体应用实战课/开篇词｜天作之合：LLM助力业务流程自动化.md","filePath":"LLM自主智能体应用实战课/开篇词｜天作之合：LLM助力业务流程自动化.md","lastUpdated":1779815961000}'),s={name:"LLM自主智能体应用实战课/开篇词｜天作之合：LLM助力业务流程自动化.md"};function i(A,t,l,r,p,B){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="开篇词-天作之合-llm助力业务流程自动化" tabindex="-1">开篇词｜天作之合：LLM助力业务流程自动化 <a class="header-anchor" href="#开篇词-天作之合-llm助力业务流程自动化" aria-label="Permalink to &quot;开篇词｜天作之合：LLM助力业务流程自动化&quot;">​</a></h1><p>你好，我是李锟，欢迎和我一起来学习如何开发 LLM 驱动的 BPA 应用。</p><p>自我介绍一下，我是一名资深的软件业务架构师，在IT行业工作二十多年，曾在阿里巴巴、盛付通、唯品会等公司就职。目前已创业多年，担任上海霓风网络科技有限公司的CEO。平时的主要工作是从事 AI + LLM 行业应用的研发、咨询、培训，面向的主要行业包括量化投资、在线教育、电商、旅游。</p><p>随着科学技术各个学科知识体系的细分和深入，我们在单一学科里面取得大的技术成果越来越困难，更多的技术成果是来自于一些跨学科领域。同时，企业对于复合型技术人才的需求也越来越多。打造自己的核心竞争力，时刻关注并学习一些有前途的跨学科领域，显然是明智之举。</p><p>那么我们的这套课程，就聚焦在两个很热门的技术领域—— <strong>大型语言模型（LLM）和业务流程自动化（BPA）</strong>。当这两个技术领域充分融合在一起时，会起到一加一大于二的神奇效果。</p><p>在开展学习之前，我们不妨先对业务流程自动化取得共识，再进一步明确大模型在其中起到了怎样的作用。</p><h2 id="什么是业务流程自动化" tabindex="-1">什么是业务流程自动化？ <a class="header-anchor" href="#什么是业务流程自动化" aria-label="Permalink to &quot;什么是业务流程自动化？&quot;">​</a></h2><p>首先我们来看两个定义：</p><blockquote><p>业务流程（Business Process）是为实现特定组织目标而创建的一系列活动，例如产品生产、财务处理、员工入职或获取新客户。这些流程通常跨越多个部门，涉及一系列可完全或部分自动化的任务。</p></blockquote><blockquote><p>业务流程自动化（Business Process Automation，简称 BPA）是一种使用软件来自动完成复杂及重复性业务流程的策略。BPA 的主要目标是简化日常运营以保持业务平稳运行。这些“业务运行”活动是产生收入并有助于保证业务高效运行的核心流程，例如处理订单或管理客户账户。</p></blockquote><p>从上述定义我们可以知道，BPA 是由计算机软件来完成的。我们还需要了解的是，BPA 可能会很复杂，并且会与多个企业 IT 系统集成。它是根据组织的特定需求定制的，可能会使用各种技术，包括机器人流程自动化（RPA）、工作流编排、业务流程管理（BPM）、人工智能和云计算。</p><p>BPA 在企业应用领域，一直都占据着核心位置，是企业应用中最重要的部分。可以说自从有了企业应用，就有了 BPA。按照不同的复杂程度和自动化规模，BPA 可以划分为以下五个类别（顺序为从简单到复杂）：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/838703/c8e917532a087e4ebd6672afef125c8d.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/838703/c8e917532a087e4ebd6672afef125c8d.png" alt="图片"></a></p><p>上述这些定义略显枯燥，不过你可以从中充分理解 BPA 所涵盖的范围。其中最复杂的 BPA 就是与现代 AI 技术紧密结合的 <strong>智能自动化</strong>，达到了 BPA 的最大程度和范围。不过 AI 并非只能用于最复杂的智能自动化，其实 AI 可以应用于上述所有类别的 BPA，从最简单的任务自动化到最复杂的智能自动化。</p><p>了解了 BPA，我们再来谈谈 LLM 对 BPA 应用的帮助。</p><h2 id="llm-助力业务流程自动化" tabindex="-1">LLM 助力业务流程自动化 <a class="header-anchor" href="#llm-助力业务流程自动化" aria-label="Permalink to &quot;LLM 助力业务流程自动化&quot;">​</a></h2><p>如今 LLM 已经发展成为一个庞大的生态系统，诞生了各种通用的大语言模型 + 行业/领域专用大语言模型、云端商业大语言模型+ 开源大语言模型、大语言模型部署方案、大语言模型应用开发框架，百花齐放，争奇斗艳。所以今后两年（2025～2026年）正是开发各种 LLM 应用的黄金时间。</p><p>从前面对 BPA 的介绍中，我们了解到 AI 技术已经与 BPA 紧密结合。既然如此，那么当今 AI 技术的最大热点——大语言模型，也必然能与 BPA 紧密结合，甚至可以说是天作之合。</p><p>BPA 的目标就是使用应用软件实现的业务逻辑，以及使用应用软件驱动相关硬件设备，来完成之前需要大量人力来完成的各种工作。</p><p>在大语言模型诞生之前，各种 BPA 应用都是定制化的，仅能覆盖特定的工作。如果有新的工作类型需要实现自动化，对不起，需要另外再开发一套 BPA 应用。</p><p>有了大语言模型，就有可能 <strong>开发出更加通用的、全面的自动化应用</strong>。这类应用能够使用自然语言来与人类交互（NUI 界面），而且能够理解和处理大量自然语言的文本（非结构化数据），还配备有各种可以调用的外部工具。</p><p>人类对待这类自动化应用，就好像是对待一位在工作中执行任务的工友那样。只需要将工作的目标、背景、交付物的质量要求讲清楚，这位工友就能够根据自己的能力来制定计划、分解任务，然后自主地完成工作，最终交付人类所需要的交付物。</p><p>这时候你可能会自然地想到 ChatBot？不，我们想要实现的有效推动业务流程自动化的产物远不止于此。我们真正需要的是超越普通 ChatBot 的另一类智能体应用—— <strong>Autonomous Agent (自主型智能体)。</strong></p><p>上述这位工友的能力，显然已经超出了传统的只能完成单一工作的那些低层次自动化应用。你渴望未来有这样一位任劳任怨的工友来帮助你的工作吗？</p><p>这不是天马行空的幻想，我可以带你将其变为现实。</p><h2 id="llm-应用开发框架的分类" tabindex="-1">LLM 应用开发框架的分类 <a class="header-anchor" href="#llm-应用开发框架的分类" aria-label="Permalink to &quot;LLM 应用开发框架的分类&quot;">​</a></h2><p>由大语言模型驱动的能够独立自主完成工作的智能体应用，这类应用有一个自己的专属名词——Autonomous Agent。这个名词比较精确，因为它突出了 “Autonomous”，意思是说这类智能体应用是自主型的，大多数时候都可以独立自主完成工作，并不需要人类来反复干涉、反复指导。而且这类智能体应用还有很强的主动性，能够主动向人类提出建设性意见、建议，主动与人类沟通，以便更好地完成工作目标。这与另外一类常见的智能体应用——ChatBot 形成了鲜明的对比。</p><p>最著名的 ChatBot 当然就是 ChatGPT 了。它是一个问答、对话型的智能体应用，可以与人类无限期聊天，回答人类提出的各种问题。但是它是被动型的，不会主动跟人类沟通，只有人类发起对话后才会作出答复。ChatBot 在很多领域非常有用，例如基于行业知识库的问答机器人、客服机器人、营销机器人等等。</p><p>然而当涉及到 BPA 领域，ChatBot 就力不从心了，基于 ChatBot 来开发 BPA 应用，会显得很笨拙。 例如一个多 Agent 的软件开发团队，产品经理编写需求，项目经理分解任务、制定计划并分配任务，程序员编写程序，测试工程师测试。这样复杂的工作协作是普通的 ChatBot 完全无法实现的。还有很多在工业场景中完成特定任务的智能体应用，需要高度的自动化，交互模式跟 ChatBot 完全不同。</p><p>因此， <strong>在 BPA 这个场景中，我们需要开发的并不是 ChatBot，而是 Autonomous Agent。</strong> 现存的 LLM 应用开发框架，因此也可以划分为两大类：</p><ul><li><p>主要面向开发 ChatBot 的，例如 LangChain、Llama Index。大多数流行的所谓 RAG 开发框架、低代码开发框架（DiFy、Coze 等等），也属于这一类。</p></li><li><p>主要面向开发 Autonomous Agent 的，例如 AutoGPT、BabyAGI、Camel、MetaGPT、AutoGen（微软）、AutoAgents、Swarm（OpenAI）等等。这类开发框架都已经能够支持开发多 Agent 应用，可用于开发有复杂工作流的自动化应用。</p></li></ul><p>除了上述两大分类外，还有一类支持 <strong>自动化提示词工程</strong> 的开发框架，在 BPA 应用开发领域也会越来越重要，可以缓解并解决复杂手工提示词工程中存在的工作繁重、脆弱、不可移植、技能难以在团队中传播等严重问题。最早诞生的自动化提示词工程开发框架是斯坦福大学的 DSPy，还有中国开发者创建的 Minion 等几个成长中的开源项目。这一类开发框架可以与上述两大类开发框架结合起来使用。</p><h2 id="课程设计" tabindex="-1">课程设计 <a class="header-anchor" href="#课程设计" aria-label="Permalink to &quot;课程设计&quot;">​</a></h2><p>我开设这门课程的目的就是带你学习一套实用技术，最终掌握开发 LLM 驱动的 BPA 应用的技能。简单点说，就是独立开发 Autonomous Agent，并且与你的业务完美结合。</p><p>那我们具体学习哪些内容呢？</p><p><strong>准备篇：</strong> 对于 Autonomous Agent 有清晰的概念，充分理解 Autonomous Agent 与 ChatBot 的区别，以及开发 Autonomous Agent 的复杂性，并做好充分的上手准备。</p><p><strong>入门篇：</strong> 掌握 3 种最流行的 Autonomous Agent 开发框架和 1 种自动提示词工程开发框架的使用方法。通过实现简单的业务需求，在实战中学习各种开发框架。</p><p><strong>进阶篇：</strong> 从产品和架构设计的角度，学习设计复杂 Autonomous Agent 的要点，并参与设计、开发一个真实的行业应用——企业员工 AI 助理。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/838703/fc86a40e8fa94b734e7ed30014066bf3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/838703/fc86a40e8fa94b734e7ed30014066bf3.png" alt="图片"></a></p><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>最后，我们不妨畅想一下，在 LLM 之后会出现什么呢？有很多业界 AI 专家预言，真正的 <strong>通用人工智能 AGI</strong>（Artificial General Intelligence）即将诞生，人类即将进入一个全新的 AGI 时代。大多数普通人往往会高估 AI 在三年之内的发展，同时又会低估 AI 在五年之后的发展。对于 AGI，即便我们做一个不是非常乐观的估计，未来十年内也会诞生。AGI 的发展会持续几十年，并且会与未来十年内将会诞生的通用量子计算机、硅光子芯片等等强大得多的算力紧密结合。</p><p>我们课程中介绍的技能，会帮助你充分适应未来的 AGI 时代。希望这套课程能成为你迈进 AGI 时代的入场券，成为未来的优胜者！</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/838703/f6f99d6754d5dd506c83e4148bb27542.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/LLM%E8%87%AA%E4%B8%BB%E6%99%BA%E8%83%BD%E4%BD%93%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98%E8%AF%BE/images/838703/f6f99d6754d5dd506c83e4148bb27542.png" alt="图片"></a></p>',43)])])}const g=e(s,[["render",i]]);export{h as __pageData,g as default};
